# More parameters = more capacity to overfit
models = {
    "tiny":  (100, "high underfit risk"),
    "small": (10000, "balanced"),
    "huge":  (10000000, "high overfit risk"),
}

for name, (params, note) in models.items():
    print(f"{name}: {params:,} params — {note}")

# The overfitting signature
def diagnose(train_acc, test_acc):
    gap = train_acc - test_acc
    if gap > 0.15:
        return "Overfitting — large train/test gap"
    elif train_acc < 0.65:
        return "Underfitting — model too simple"
    else:
        return "Healthy — train and test close"

print(diagnose(0.99, 0.75))   # Overfitting
print(diagnose(0.55, 0.53))   # Underfitting
print(diagnose(0.85, 0.83))   # Healthy

